// Logo bytes copied into this repo. Served by the Worker so member pages do not hotlink.
const FILES = {
  "/assets/networks/walton-county-business-leaders-logo.png": { type: "image/png", base64: "" },
  "/assets/networks/walton-county-builders-network-logo.jpg": { type: "image/jpeg", base64: "" },
  "/assets/networks/walton-county-tourism-network-logo.webp": { type: "image/webp", base64: "" }
};

export function networkLogo(path) {
  const item = FILES[path];
  if (!item) return null;
  const binary = atob(item.base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return { type: item.type, bytes };
}
